/* Extracted from the approved original; reorganized for this portable edition. */
(L => {
  "use strict";

  L.art = id => {
    const p = L.products.find(x => x.id === id);
    return `<div class="product-art"><img src="assets/images/${p.image}.webp" alt="${p.alt} — sample product reference" loading="lazy" width="800" height="1100"><span class="tag">SAMPLE PRODUCT</span><small>STOCK PHOTO · FINAL PRODUCT TO COME</small></div>`;
  };
  L.cards = (limit = location.hash.startsWith("#shop") ? 99 : 4) => {
    const results = L.filteredProducts().slice(0, limit);
    if (!results.length) return '<div class="empty-products"><h3>A different kind of celebration?</h3><p>No sample designs match both filters. Clear them to explore the collection, or call about a custom arrangement.</p><button class="button" data-reset-filters>Show all balloons</button><a class="text-link" href="tel:+16618605930">Ask Luna’s ↗</a></div>';
    return results.map(p => `<article class="product-card"><button class="product-image-button" data-product="${p.id}" aria-label="View ${p.name}">${L.art(p.id)}</button><div class="product-info"><span class="category">${p.featured ? '<span class="featured-label">FEATURED CONCEPT · </span>' : ''}${p.category}</span><h3><button data-product="${p.id}">${p.name}</button></h3><p class="product-description">${p.description}</p><div class="card-bottom"><span class="price">${L.money(p.price)}<small>Demo price</small></span><button class="details-link" data-product="${p.id}" aria-label="View details for ${p.name}">Details ↗</button></div><button class="add-to-bag" data-add="${p.id}" aria-label="Add ${p.name} to the sample bag">Add to Sample Bag <span>+</span></button><p class="default-option">Demo: ${p.colors[0]}${p.id === 'number' ? ' · Number 2' : ''}</p></div></article>`).join('');
  };
  L.categories = () => `<div class="filters" aria-label="Product categories">${["All balloons", "Bouquets", "Number balloons", "Party bundles", "Single balloons", "Bubble gifts"].map(c => `<button class="filter" data-shop-filter="${c}" aria-pressed="${c === L.shopFilter}">${{
    "All balloons": "All Balloons",
    "Number balloons": "Number Balloons",
    "Party bundles": "Party Bundles",
    "Single balloons": "Single Balloons",
    "Bubble gifts": "Bubble Gifts"
  }[c] || c}</button>`).join("")}</div>`;
  L.servicesMini = () => `<div class="service-editorial">${L.serviceData.map((s, i) => `<article class="service-story">${L.photo(s[2], s[3])}<div class="service-copy"><span class="number">0${i + 1}</span><h3>${s[0]}</h3><p>${s[1]}</p><a class="text-link" href="#contact?service=${encodeURIComponent(s[4] || s[0])}">Discuss this service <span>→</span></a></div></article>`).join("")}</div>`;
  L.galleryPreview = () => `<section class="home-gallery balanced-gallery section" aria-labelledby="work-title"><div class="wrap"><div class="section-head"><div><p class="eyebrow">THE MOMENTS WE CREATE</p><h2 id="work-title">Thoughtfully designed.<br><em>Beautifully celebrated.</em></h2></div><div class="section-intro"><p>Explore celebrations, installations, and special moments brought to life through creative details and personalized design.</p><a class="text-link" href="#gallery">View Our Gallery →</a></div></div><div class="home-gallery-photos">${[["balloon-installation", "Cream, peach and gold balloon installation with greenery", "Balloon installations"], ["event-table", "A floral celebration tablescape", "Event styling & decorations"], ["intimate-celebration", "An intimate gathering with balloons, flowers and lanterns", "Personalized celebrations"], ["birthday-room", "Pastel birthday balloons and lettering in a room", "Room décor & surprises"]].map(p => `<article>${L.photo(p[0], p[1])}<h3>${p[2]}</h3></article>`).join("")}</div><p class="gallery-reference-note">Licensed stock references, not Luna’s completed work. Original project photographs will be added with the owners’ approval.</p></div></section>`;
  L.process = () => `<section class="process-section section"><div class="wrap process-layout"><div><p class="eyebrow">FROM AN IDEA TO AN OCCASION</p><h2>Let’s plan<br>something <em>you.</em></h2><p>Start with what you know.<br>We’ll talk through the rest.</p><a class="text-link" href="#contact">Start your event inquiry ↗</a></div><ol class="process-list"><li><span>01</span><div><h3>Tell us about your celebration.</h3><p>Share your date, location, colors and inspiration.</p></div></li><li><span>02</span><div><h3>We’ll talk through the details.</h3><p>Discuss your vision, availability and the right services.</p></div></li><li><span>03</span><div><h3>Review, then confirm.</h3><p>Agree on your event details and booking terms before confirming.</p></div></li></ol></div></section>`;
  L.storefront = () => `<section class="storefront"><div class="store-image">${L.photo("birthday-bouquet", "Soft pink, ivory and lavender birthday balloons")}</div><div class="store-copy"><p class="eyebrow">COMING SOON TO HUMBLE</p><h2>A little shop.<br>A lot to <em>celebrate.</em></h2><p>Our Humble balloon boutique is coming. The celebrations don’t have to wait.</p><p class="muted">Balloons are available to purchase now while we prepare our physical shop. Contact Luna’s for current products and ordering details.</p><div class="actions"><a class="button dark" href="#shop">Shop Balloons ↗</a><a class="text-link" href="tel:+16618605930">Ask about store updates ↗</a></div><p class="fine">Opening date and address to be announced.</p></div><div class="store-stamp">LUNA’S<br><span>BALLOON<br>BOUTIQUE</span><small>HUMBLE, TX</small></div></section>`;
  L.pageIntro = (label, title, desc) => `<section class="page-top"><div class="wrap"><p class="eyebrow">${label}</p><h1>${title}</h1><p class="lead">${desc}</p></div></section>`;
  L.pages = {
    home: () => `<section class="hero immersive-hero balanced-hero" aria-labelledby="hero-title"><figure class="hero-photo"><img src="assets/images/pink-gold-celebration.webp" alt="Pink, ivory and gold balloon installation — licensed stock reference, not Luna’s work" width="1900" height="1267" fetchpriority="high"><figcaption>Licensed stock reference · Not Luna’s portfolio</figcaption></figure><div class="hero-copy"><p class="eyebrow">LUNA’S LUXURY EVENTS HTX · HUMBLE, TEXAS</p><h1 id="hero-title">Every celebration deserves <em>beautiful details.</em></h1><p class="hero-subheadline">Beautiful balloons.<br><em>Thoughtful event experiences.</em></p><p>From personalized balloon arrangements to beautifully styled events, Luna’s Luxury Events HTX brings your celebrations to life. Discover our balloon boutique or let us create something unforgettable for your next special occasion.</p><div class="actions balanced-actions"><a class="button dark" href="#shop">Shop Balloons <span aria-hidden="true">→</span></a><a class="button outline" href="#services">Explore Event Services <span aria-hidden="true">→</span></a></div><div class="hero-local"><span class="mini-diamond" aria-hidden="true">◇</span><span>Husband-and-wife-owned. Personally planned. Beautifully celebrated.</span></div><p class="hero-boutique-note">Our Humble balloon boutique is coming soon. <a href="tel:+16618605930">Current balloon inquiries welcome.</a></p></div></section><section class="services-section section" aria-labelledby="services-title"><div class="wrap"><div class="section-head"><div><p class="eyebrow">OUR SERVICES</p><h2 id="services-title">Your occasion.<br><em>Our attention to the details.</em></h2></div><p class="section-intro">From intimate surprises to unforgettable celebrations, we bring thoughtful planning, creative styling, and beautiful details to every occasion.</p></div>${L.servicesMini()}<div class="section-action"><a class="button dark" href="#services">Explore All Event Services →</a></div></div></section><section class="shop-section section" aria-labelledby="boutique-title"><div class="wrap"><div class="section-head"><div><p class="eyebrow">THE BALLOON BOUTIQUE</p><h2 id="boutique-title">Small surprises.<br><em>Big celebration energy.</em></h2></div><div class="section-intro"><p>From everyday surprises to milestone moments, find beautiful balloons to make someone smile. Explore personalized arrangements, celebration bouquets, number balloons, and more.</p><a class="text-link" href="#shop">Explore the Balloon Boutique →</a></div></div>${L.categories()}<div id="products" class="products">${L.cards()}</div><p class="shop-disclosure"><span>SHOP PREVIEW</span> Sample products, options, stock photos and demo prices. This website does not process orders or payments. Contact Luna’s for current products and ordering details.</p></div></section>${L.occasionSection()}${L.galleryPreview()}${L.celebrationPaths()}`,
    shop: () => `<section class="shop-masthead"><div class="wrap shop-masthead-inner"><div><p class="eyebrow">THE BALLOON BOUTIQUE</p><h1>A good day<br>to <em>celebrate.</em></h1><p>Balloons are available before our Humble store opens.<br>Explore sample ideas, then ask Luna’s for the current collection.</p></div><div class="shop-collage"><img src="assets/images/birthday-bouquet.webp" alt="Birthday bouquet — sample product stock reference" width="800" height="1200"><img src="assets/images/bubble-gift.webp" alt="Bubble balloon gift — sample product stock reference" width="800" height="1200"><span>STOCK PRODUCT REFERENCES</span></div></div></section><section class="section wrap shop-catalog"><div class="shop-toolbar"><div><h2>Find your celebration.</h2><p class="catalog-count" id="product-count" role="status" aria-live="polite">6 sample designs · No live inventory</p></div><button class="text-link cart-toggle">View Sample Bag ↗</button></div><p class="shop-disclosure"><span>SHOP PREVIEW</span> Sample products, photos and prices. No orders or payments are processed.</p>${L.categories()}${L.occasionFilters()}<p id="filter-status" class="filter-status" role="status" aria-live="polite"></p><div id="products" class="products">${L.cards()}</div><div class="fulfillment"><div><span>01 / BEFORE YOU ORDER</span><h3>Receiving your balloons</h3><p>Ask Luna’s how to receive your balloons and confirm any fees and timing before agreeing to an order. Pickup and delivery arrangements are still being finalized.</p></div><div><span>02 / FOR A BIGGER IDEA</span><h3>Need a custom setup?</h3><p>Arches, garlands and event installations begin with an inquiry so we can understand your space and vision.</p><a class="text-link" href="#contact?service=Balloon%20backdrops">Plan a custom balloon design ↗</a></div></div></section>${L.howToOrder()}${L.shoppingFAQ()}`,
    services: () => `${L.pageIntro("BALLOON DECOR · EVENT PLANNING · ROOM DECOR", "Let’s bring your<br><em>celebration to life.</em>", "Three ways to make your occasion feel personal. Share your date and location so we can discuss the right services and availability.")}<section class="wrap section services-full">${L.serviceData.map((s, i) => `<article class="service-detail">${L.photo(s[2], s[3])}<div><p class="eyebrow">0${i + 1} / CUSTOM EVENT SERVICES</p><h2>${s[0]}</h2><p>${s[1]}</p><p class="muted">Share your date, location and inspiration. We’ll discuss availability, scope and pricing before you commit.</p><div class="actions"><a class="button dark" href="#contact?service=${encodeURIComponent(s[4] || s[0])}" aria-label="Plan ${s[0]}">Plan this service →</a><a class="text-link" href="#gallery">View celebration inspiration →</a></div></div></article>`).join("")}</section>${L.process()}`,
    about: () => `${L.pageIntro("HUSBAND & WIFE OWNED · HUMBLE, TEXAS", "A local team.<br><em>A personal reason to celebrate.</em>", "Luna’s Luxury Events HTX brings balloon decor, event planning and room surprises together in one local business.")}<section class="section wrap about-introduction"><div class="owner-portrait"><div class="portrait-outline" aria-hidden="true">◇</div><h2>Meet the owners</h2><p>A photograph of the husband-and-wife team will go here.</p><span>ORIGINAL OWNER PHOTO TO COME</span><img src="assets/logo/lunas-logo.jpg" alt="Luna’s Luxury Events HTX logo" width="70" height="70"></div><div class="about-copy"><p class="eyebrow">HELLO FROM HUMBLE</p><h2>Tell us what<br>you’re <em>imagining.</em></h2><p>We’re the husband-and-wife team behind Luna’s Luxury Events HTX. Based in Humble, we offer balloon backdrops, event planning and room decor for celebrations around the Houston area.</p><p>Maybe you have every color picked out. Maybe you just know you want to make someone’s day. Share where you’re starting, and we’ll talk through your ideas, date and location.</p><p>Looking for a smaller surprise? Explore the balloon boutique preview, or call us to ask about current availability.</p><div class="actions"><a class="button dark" href="#contact">Tell us about your event ↗</a><a class="text-link" href="#shop">Explore the balloon shop ↗</a></div></div></section><section class="section wrap about-storefront">${L.storefront()}</section>`,
    gallery: () => `${L.pageIntro("CELEBRATION INSPIRATION", "A little inspiration<br><em>for your next occasion.</em>", "Explore styles and possibilities. These licensed stock references show the design direction; Luna’s completed-project gallery will follow with the owners’ original photos.")}<section class="section wrap gallery-section"><div class="filters" aria-label="Gallery categories">${["All", "Birthdays", "Baby showers", "Weddings", "Custom events", "Room decorations"].map(c => `<button class="filter" data-gallery-filter="${c}" aria-pressed="${L.galleryFilter === c}">${c}</button>`).join("")}</div><div class="gallery-grid">${[["Birthdays", "birthday-setup", "Birthday party setup with balloons and fairy lights"], ["Baby showers", "intimate-celebration", "Celebration table with balloons and flowers"], ["Weddings", "event-table", "Formal event table with floral arrangements"], ["Custom events", "birthday-room", "A pastel balloon room setup"], ["Room decorations", "room-decor", "Rose-petal heart and white balloons in a bedroom"]].filter(c => L.galleryFilter === "All" || L.galleryFilter === c[0]).map(c => `<article>${L.photo(c[1], c[2])}<h3>${c[0]}</h3><p>Inspiration only · Not a completed Luna’s project</p><a class="text-link" href="#contact">Tell us about your idea ↗</a></article>`).join("")}</div></section>`,
    contact: () => `<section class="inquiry-page"><div class="wrap"><div class="inquiry-heading"><p class="eyebrow">YOUR OCCASION. YOUR VISION.</p><h1>Let’s make it<br><em>something special.</em></h1><p>Tell us a little about your celebration.<br>We’ll start with your idea and talk through the details.</p></div><div class="contact-grid"><div class="form-shell"><div class="form-preview"><span>INQUIRY PREVIEW</span> Nothing is sent or booked. Use sample details to try it.</div><ol class="form-progress" aria-label="Inquiry progress"><li data-progress="0" aria-current="step"><span>1</span>Your details</li><li data-progress="1"><span>2</span>Your event</li><li data-progress="2"><span>3</span>The inspiration</li></ol><div id="form-area"><form id="inquiry"><fieldset class="form-section" data-step="0"><legend>Your details</legend><p class="form-help">How could we reach you about your celebration?</p><div class="fields"><label class="field full">Your name *<input name="name" autocomplete="name" placeholder="First and last name" required maxlength="120"></label><label class="field full">Preferred contact method<select name="contact-method"><option value="email">Email</option><option value="phone">Phone call</option></select></label><label class="field full"><span id="email-label">Email address *</span><input name="email" type="email" autocomplete="email" placeholder="you@example.com" required maxlength="180"></label><label class="field full"><span id="phone-label">Phone number (optional)</span><input name="phone" type="tel" autocomplete="tel" placeholder="Your best contact number" maxlength="40"></label></div></fieldset><fieldset class="form-section" data-step="1" hidden><legend>Your celebration</legend><p class="form-help">A few practical details help us understand your plans.</p><div class="fields"><label class="field">Event type *<select name="type" required><option value="">Choose an occasion</option><option>Birthday</option><option>Baby shower</option><option>Wedding celebration</option><option>Anniversary</option><option>Corporate event</option><option>Other celebration</option></select></label><label class="field">Event date *<input name="date" type="date" required></label><label class="field full">Event location *<input name="location" placeholder="Venue or city, if known" required maxlength="220"><small>We’ll confirm service availability at your location.</small></label><div class="field full"><span id="services-label">What can we help with?</span><div class="checks" role="group" aria-labelledby="services-label">${["Balloon backdrops", "Event planning", "Room decor", "Custom event design"].map(s => `<label><input name="services" type="checkbox" value="${s}">${s}</label>`).join("")}</div></div><label class="field full">Estimated budget (optional)<input name="budget" placeholder="Your approximate budget in USD" maxlength="80"></label></div></fieldset><fieldset class="form-section" data-step="2" hidden><legend>The inspiration</legend><p class="form-help">Share what you’re imagining. It’s okay to still be figuring it out.</p><div class="fields"><label class="field full">Tell us about your event *<textarea name="description" required maxlength="3000" placeholder="Your theme, favorite colors, guest count and any details you have in mind."></textarea></label><label class="field full upload-field">Add an inspiration image (optional)<input name="inspiration" type="file" accept="image/jpeg,image/png,image/webp"><small>JPG, PNG or WebP · Up to 5 MB. Selected locally; no file is uploaded.</small><span id="file-feedback" role="status"></span></label><button type="button" class="text-link clear-image" id="clear-inspiration" hidden>Clear image selection</button></div><p class="fine inquiry-terms">An inquiry starts a conversation. Your event is confirmed only after the details and booking terms are agreed.</p></fieldset><div class="form-actions"><button type="button" class="text-link" id="previous-step" hidden>← Back</button><span id="step-label" role="status" aria-live="polite">Step 1 of 3</span><button class="button dark" id="next-step" type="button">Your Event <span>→</span></button><button class="button dark" id="submit-inquiry" type="submit" hidden>Preview Inquiry <span>↗</span></button></div></form></div></div><aside class="inquiry-aside">${L.photo("birthday-room", "Pastel balloons and birthday lettering — stock reference")}<div class="aside-copy"><p class="eyebrow">LET’S TALK THROUGH YOUR IDEAS</p><h2>Prefer a conversation?</h2><p>Call us directly for a real inquiry.</p><a class="phone-link" href="tel:+16618605930">661-860-5930 ↗</a><div class="aside-next"><h3>What happens next?</h3><p>We’ll discuss your vision and availability, then agree on the details before any booking is confirmed.</p></div><p class="fine">Humble & the surrounding Houston area.<br>Exact service coverage and response times to be confirmed.</p></div></aside></div></div></section>`,
    review: () => `${L.pageIntro("PRIVATE CLIENT PROTOTYPE", "A new direction.<br><em>A clear path to launch.</em>", "Balloons are available before the Humble boutique opens. This demonstration pairs clear shopping guidance with a welcoming event inquiry experience.")}<section class="section wrap notes-grid"><article><h2>What works</h2><ul><li>Responsive six-page navigation, desktop inquiry button and mobile menu.</li><li>Product and occasion filters, featured concepts, sample options, quantities and editable session-only bag.</li><li>Order-discussion panel and copyable sample selections; no checkout or payments.</li><li>Three-step inquiry with required field validation, local image selection and clear demonstration confirmation.</li><li>Inspiration gallery filters, direct phone and supplied social handle links.</li></ul></article><article><h2>What is still a sample</h2><p>All shop products, prices and stock images are illustrative. No inventory is reserved. Inquiries, files and payments are not transmitted. Bag and form contents clear on refresh. Stock photography does not represent Luna’s work.</p></article><article><h2>Needed from the owners</h2><ul><li>Actual event, product and owner photos with approval to use them.</li><li>Confirmed products, options, pricing, lead times and inventory.</li><li>Pickup/delivery terms, coverage and fees.</li><li>Booking, deposit, cancellation and response policies.</li><li>Contact email, confirmed social URLs, high-resolution logo and owner introduction.</li><li>Storefront address, hours and opening details when ready.</li></ul></article><article><h2>Before a public launch</h2><p>Approve content and design; add real photography; integrate inventory, secure payments, taxes, fulfillment, inquiry management, secure uploads, notifications and spam protection; finalize policies; configure domain, hosting, local SEO and consent-aware analytics. Complete device, accessibility and full transaction testing.</p></article><article class="photo-credits"><h2>Photography credits</h2><p>Licensed Pexels references, used as placeholders under the <a href="https://www.pexels.com/license/" target="_blank" rel="noopener">Pexels license ↗</a>.</p><ul>${[["10651684", "Balloon installation · Melike B"], ["7548036", "Birthday setup · amanda cavalcante"], ["17023147", "Event tablescape · Matheus Bertelli"], ["36845211", "Room decor · Nadin Sh"], ["3402029", "Balloon bouquet · cottonbro studio"], ["7180735", "Number balloons · Pavel Danilyuk"], ["5725971", "Gold balloon · Kaboompics"], ["32899559", "Pastel balloon details · Aedrian Salazar"], ["34260120", "Pink and gold installation · Justin Agyarko"], ["28786205", "Bubble balloon gift · Mehrajul Karim"], ["17285664", "Birthday bouquet · Мартич Анна"], ["7327987", "Party preparation · PNW Production"], ["7599526", "Birthday room · Thirdman"], ["9509563", "Intimate celebration · Huynh Van"]].map(c => `<li><a href="https://www.pexels.com/photo/${c[0]}/" target="_blank" rel="noopener">${c[1]} ↗</a></li>`).join("")}</ul></article><article><h2>Prototype testing</h2><p>JavaScript syntax, route rendering and sample shopping/inquiry logic are checked. Browser and real-device visual review must be completed before production. No payment, email or booking integration is claimed.</p></article></section>`
  };
})(window.Luna);
